sys_transform_script.script:
(function runTransformScript(source, map, log, target /*undefined onStart*/ ) {
	if(source.opid!=''){
		target.setValue('table',"x_onpr_onpage_target");
	}
	if(source.onpage_name!=''){
		target.setValue('table',"sys_group");
	}
	else{
		target.setValue('table',"sys_user");
	}

})(source, map, log, target);
